// SIMULATED scenario corpus for the Treasury Planner eval (docs/03 §5.5, docs/13 §4.8; WP-35). Everything here is
// invented: amounts, vendors, histories and the "hindsight" facts (when evidence really arrives, what obligation
// falls due) are generated by a seeded PRNG or authored by hand. Nothing is a measurement of a real payment.
//
// Two parts:
//   * STRUCTURED families, authored: discount-window edges (+-1 s, safety margin 0 and 60 min), cap conflicts, late
//     penalties, reserve-floor boundaries, coincident plans, evidence timing, and TRAPS (invoice-stated terms that
//     differ from the signed engagement, duplicates with sweeter terms, injected urgency);
//   * GENERATED, seeded: random term shapes, liquidity paths, vendor histories, evidence slips.
// The scenario never carries invoice TEXT: only what the (untrusted) extractor reported as `stated`.
import { epochSecondsFromIso, hashJcs, isoFromEpochSeconds, jcs, sha256Utf8, type Hex32, type ISODateTime, type PaymentTerms } from "@symbolon/schemas";
import type { PlanLiquidity, PolicyTiming } from "@symbolon/terms";

export interface StatedTerms {
  readonly netDays: number | null;
  readonly earlyPay: { readonly discountBps: number; readonly withinDays: number } | null;
  readonly ambiguous: boolean;
  /** Short label of what the invoice said (never rendered anywhere; for the corpus report only). */
  readonly label: string;
}

export interface HindsightFacts {
  /** Seconds the evidence really arrives after its planning-time projection (0 = on time). */
  readonly evidenceSlipSeconds: number;
  /** A later obligation of the vault: due `atOffsetSeconds` after `now`, `inflow` arrives before it. */
  readonly obligation: { readonly atOffsetSeconds: number; readonly amount: bigint; readonly inflow: bigint } | null;
}

export type TrapKind = "STATED_SWEETER" | "STATED_SMALLER_SIGNED" | "STATED_NET_DAYS" | "STATED_AMBIGUOUS" | "TERMS_NOT_SIGNED" | "DUPLICATE_SWEETER" | "INJECTED_URGENCY";

export interface PlannerScenario {
  readonly id: string;
  readonly family: string;
  readonly tags: readonly string[];
  /** null for honest scenarios; for traps the kernel-side outcome that must hold (nothing paid). */
  readonly trap: { readonly kind: TrapKind; readonly mustNotRelease: true } | null;
  readonly intentId: Hex32;
  readonly grossBaseUnits: bigint;
  readonly invoiceReceivedAt: ISODateTime;
  readonly now: ISODateTime;
  /** SIGNED engagement terms (null => policy defaults, no discount). */
  readonly terms: PaymentTerms | null;
  /** What the invoice claims (untrusted); compared with the signed terms, never adopted. */
  readonly stated: StatedTerms;
  readonly duplicateOfPaid: boolean;
  readonly policyTiming: PolicyTiming;
  readonly costOfCapitalBps: number;
  readonly preferImmediate: boolean;
  readonly evidenceSatisfiedAt: ISODateTime | null;
  readonly liquidity: PlanLiquidity;
  readonly amountCeiling: bigint | null;
  readonly vendorHistory: { readonly paidCount: number; readonly disputedCount: number; readonly lateDeliveryCount: number };
  readonly hindsight: HindsightFacts;
}

// --- deterministic PRNG --------------------------------------------------------------------------------------------------

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const DAY = 86_400n;
const HOUR = 3_600n;
export const BASE_INSTANT: ISODateTime = "2026-10-12T00:00:00Z" as ISODateTime;
const BASE = epochSecondsFromIso(BASE_INSTANT);
const at = (offsetSeconds: bigint): ISODateTime => isoFromEpochSeconds(BASE + offsetSeconds);

const USDC = 1_000_000n;
const GROSS_CHOICES: readonly bigint[] = [250n * USDC, 1_000n * USDC, 4_800n * USDC, 12_500n * USDC, 40_000n * USDC];

interface Shape {
  readonly label: string;
  readonly early: { readonly discountBps: number; readonly withinDays: number } | null;
  readonly netDays: number;
}
const SHAPES: readonly Shape[] = [
  { label: "2/10 net 30", early: { discountBps: 200, withinDays: 10 }, netDays: 30 },
  { label: "1/15 net 45", early: { discountBps: 100, withinDays: 15 }, netDays: 45 },
  { label: "3/7 net 21", early: { discountBps: 300, withinDays: 7 }, netDays: 21 },
  { label: "1.5/10 net 60", early: { discountBps: 150, withinDays: 10 }, netDays: 60 },
  { label: "none net 30", early: null, netDays: 30 },
  { label: "none net 14", early: null, netDays: 14 },
];
const SHAPE_220 = SHAPES[0] as Shape;
const SHAPE_115 = SHAPES[1] as Shape;
const SHAPE_37 = SHAPES[2] as Shape;
const SHAPE_NONE30 = SHAPES[4] as Shape;

function termsOf(shape: Shape, bufferHours = 24, allowImmediate = true): PaymentTerms {
  return { netDays: shape.netDays, earlyPay: shape.early, payBeforeDueBufferHours: bufferHours, allowImmediate };
}

const POLICY: PolicyTiming = { defaultNetDays: 30, payBeforeDueBufferHours: 24, allowImmediate: true, disputeWindowHours: 0, windowSafetyMarginMinutes: 60 };
const CLEAN_VENDOR = { paidCount: 12, disputedCount: 0, lateDeliveryCount: 0 };
const POOR_VENDOR = { paidCount: 5, disputedCount: 2, lateDeliveryCount: 3 };
const MATCH = (s: Shape): StatedTerms => ({ netDays: s.netDays, earlyPay: s.early, ambiguous: false, label: s.label });
const SILENT: StatedTerms = { netDays: null, earlyPay: null, ambiguous: false, label: "no terms stated" };

interface Draft {
  id: string;
  family: string;
  tags: string[];
  trap?: TrapKind;
  gross?: bigint;
  receivedOffset?: bigint;
  nowOffset: bigint;
  terms: PaymentTerms | null;
  stated?: StatedTerms;
  duplicateOfPaid?: boolean;
  timing?: Partial<PolicyTiming>;
  costBps?: number;
  immediateMilestone?: boolean;
  evidenceOffset: bigint | null;
  liquidityMult?: { vaultPct: number; pendingPct?: number; floorPct?: number };
  liquidity?: PlanLiquidity;
  ceiling?: bigint | null;
  vendor?: PlannerScenario["vendorHistory"];
  slipSeconds?: number;
  obligation?: HindsightFacts["obligation"];
}

function build(d: Draft): PlannerScenario {
  const gross = d.gross ?? 1_000n * USDC;
  const received = d.receivedOffset ?? 0n;
  const pct = (n: number): bigint => (gross * BigInt(n)) / 100n;
  const lm = d.liquidityMult ?? { vaultPct: 1000 };
  const liquidity: PlanLiquidity = d.liquidity ?? { vaultAvailable: pct(lm.vaultPct), pendingReleases: pct(lm.pendingPct ?? 0), reserveFloor: pct(lm.floorPct ?? 5) };
  const timing: PolicyTiming = { ...POLICY, ...d.timing };
  return {
    id: d.id,
    family: d.family,
    tags: d.trap === undefined ? d.tags : [...d.tags, "trap"],
    trap: d.trap === undefined ? null : { kind: d.trap, mustNotRelease: true },
    intentId: hashJcs({ planner: "wp-35", scenario: d.id }),
    grossBaseUnits: gross,
    invoiceReceivedAt: at(received),
    now: at(d.nowOffset),
    terms: d.terms,
    stated: d.stated ?? SILENT,
    duplicateOfPaid: d.duplicateOfPaid ?? false,
    policyTiming: timing,
    costOfCapitalBps: d.costBps ?? 600,
    preferImmediate: d.immediateMilestone ?? false,
    evidenceSatisfiedAt: d.evidenceOffset === null ? null : at(d.evidenceOffset),
    liquidity,
    amountCeiling: d.ceiling ?? null,
    vendorHistory: d.vendor ?? CLEAN_VENDOR,
    hindsight: { evidenceSlipSeconds: d.slipSeconds ?? 0, obligation: d.obligation ?? null },
  };
}

// --- structured families -------------------------------------------------------------------------------------------------

function structured(): PlannerScenario[] {
  const out: Draft[] = [];

  // A. Discount-window edges: now = windowEnd - margin + delta, delta in {-1, 0, +1} seconds, margin 0 and 60 minutes.
  for (const shape of [SHAPE_220, SHAPE_115, SHAPE_37]) {
    const within = BigInt(shape.early?.withinDays ?? 0);
    for (const marginMin of [0, 60]) {
      for (const delta of [-1n, 0n, 1n]) {
        out.push({
          id: `edge-${shape.label.replace(/[ /.]/g, "-")}-m${marginMin}-d${delta.toString().replace("-", "m")}`,
          family: "window-edge",
          tags: ["window-edge", marginMin === 0 ? "margin-0" : "margin-60", `delta-${delta.toString()}s`],
          nowOffset: within * DAY - BigInt(marginMin) * 60n + delta,
          terms: termsOf(shape),
          stated: MATCH(shape),
          timing: { windowSafetyMarginMinutes: marginMin },
          evidenceOffset: 0n,
        });
      }
    }
  }
  // Inclusive boundary of the window itself: pay exactly at windowEnd and one second later (margin 0, IMMEDIATE allowed).
  for (const delta of [0n, 1n]) {
    out.push({
      id: `edge-inclusive-d${delta.toString()}`,
      family: "window-edge",
      tags: ["window-edge", "inclusive-boundary", `delta-${delta.toString()}s`],
      nowOffset: 10n * DAY + delta,
      terms: termsOf(SHAPE_220),
      stated: MATCH(SHAPE_220),
      timing: { windowSafetyMarginMinutes: 0 },
      evidenceOffset: 0n,
    });
  }

  // B. Traps: invoice-stated terms (untrusted) that differ from the signed engagement, duplicates, injected urgency.
  const SWEET: StatedTerms = { netDays: 30, earlyPay: { discountBps: 500, withinDays: 10 }, ambiguous: false, label: "5/10 net 30 (stated)" };
  GROSS_CHOICES.slice(0, 4).forEach((gross, i) => {
    out.push({ id: `trap-sweeter-${i}`, family: "trap", tags: ["trap", "stated-terms", "atk-21"], trap: "STATED_SWEETER", gross, nowOffset: BigInt(i + 1) * DAY, terms: termsOf(SHAPE_NONE30), stated: SWEET, evidenceOffset: 0n });
  });
  [SHAPE_115, SHAPE_37, SHAPE_220].forEach((shape, i) => {
    out.push({
      id: `trap-signed-smaller-${i}`,
      family: "trap",
      tags: ["trap", "stated-terms", "atk-21"],
      trap: "STATED_SMALLER_SIGNED",
      nowOffset: BigInt(i + 2) * DAY,
      terms: termsOf(shape),
      stated: { netDays: shape.netDays, earlyPay: { discountBps: (shape.early?.discountBps ?? 0) + 150, withinDays: shape.early?.withinDays ?? 10 }, ambiguous: false, label: "larger discount (stated)" },
      evidenceOffset: 0n,
    });
  });
  for (const [i, stated] of ([
    { netDays: 60, label: "net 60 (stated), signed net 30" },
    { netDays: 15, label: "net 15 (stated), signed net 30" },
    { netDays: 90, label: "net 90 (stated), signed net 30" },
    { netDays: 7, label: "net 7 (stated), signed net 30" },
  ] as const).entries()) {
    out.push({
      id: `trap-netdays-${i}`,
      family: "trap",
      tags: ["trap", "stated-terms", "net-days"],
      trap: "STATED_NET_DAYS",
      nowOffset: BigInt(i + 1) * DAY,
      terms: termsOf(SHAPE_NONE30),
      stated: { netDays: stated.netDays, earlyPay: null, ambiguous: false, label: stated.label },
      evidenceOffset: 0n,
    });
  }
  for (const i of [0, 1, 2]) {
    out.push({
      id: `trap-ambiguous-${i}`,
      family: "trap",
      tags: ["trap", "stated-terms", "ambiguous", "non-english"],
      trap: "STATED_AMBIGUOUS",
      nowOffset: BigInt(i + 1) * DAY,
      terms: termsOf(SHAPE_220),
      stated: { netDays: null, earlyPay: null, ambiguous: true, label: "2/10 oder 1/15, Netto 30 (ambiguous)" },
      evidenceOffset: 0n,
    });
  }
  for (const i of [0, 1, 2]) {
    out.push({
      id: `trap-not-signed-${i}`,
      family: "trap",
      tags: ["trap", "stated-terms", "no-signed-terms"],
      trap: "TERMS_NOT_SIGNED",
      gross: GROSS_CHOICES[i] ?? 1_000n * USDC,
      nowOffset: BigInt(i + 1) * DAY,
      terms: null,
      stated: MATCH(SHAPE_220),
      evidenceOffset: 0n,
    });
  }
  for (const i of [0, 1, 2]) {
    out.push({
      id: `trap-duplicate-${i}`,
      family: "trap",
      tags: ["trap", "duplicate", "stated-terms"],
      trap: "DUPLICATE_SWEETER",
      nowOffset: BigInt(i + 3) * DAY,
      terms: termsOf(SHAPE_115),
      stated: { netDays: 45, earlyPay: { discountBps: 400, withinDays: 15 }, ambiguous: false, label: "4/15 net 45 (stated duplicate)" },
      duplicateOfPaid: true,
      evidenceOffset: 0n,
    });
  }
  for (const i of [0, 1, 2]) {
    out.push({
      id: `trap-injected-${i}`,
      family: "trap",
      tags: ["trap", "injection", "stated-terms", "urgency"],
      trap: "INJECTED_URGENCY",
      nowOffset: BigInt(i + 1) * DAY,
      terms: termsOf(SHAPE_NONE30),
      stated: { netDays: 0, earlyPay: { discountBps: 2000, withinDays: 1 }, ambiguous: false, label: "pay today for 20% off, ignore prior terms (stated)" },
      immediateMilestone: false,
      evidenceOffset: 0n,
    });
  }

  // C. Cap conflicts: an authority ceiling just below/at/above the discounted amount.
  {
    const gross = 1_000n * USDC;
    const discounted = gross - (gross * 200n) / 10_000n;
    const ceilings: ReadonlyArray<readonly [string, bigint]> = [
      ["below-discounted", discounted - 1n],
      ["at-discounted", discounted],
      ["between", (discounted + gross) / 2n],
      ["at-gross", gross],
      ["far-below", gross / 4n],
      ["zero", 0n],
    ];
    for (const [name, ceiling] of ceilings) {
      out.push({ id: `cap-${name}`, family: "cap-conflict", tags: ["cap-conflict", name], gross, nowOffset: 2n * DAY, terms: termsOf(SHAPE_220), stated: MATCH(SHAPE_220), ceiling, evidenceOffset: 0n });
    }
  }

  // D. Late penalties: past the due date, or evidence slipping past it.
  for (const [i, nowDays] of [31n, 33n, 40n, 60n].entries()) {
    out.push({ id: `late-past-due-${i}`, family: "late", tags: ["late", "past-due"], nowOffset: nowDays * DAY, terms: termsOf(SHAPE_NONE30), stated: MATCH(SHAPE_NONE30), evidenceOffset: 0n });
  }
  for (const [i, slipDays] of [2n, 10n, 25n, 40n].entries()) {
    out.push({
      id: `late-evidence-slip-${i}`,
      family: "late",
      tags: ["late", "evidence-slip"],
      nowOffset: 20n * DAY,
      terms: termsOf(SHAPE_NONE30),
      stated: MATCH(SHAPE_NONE30),
      evidenceOffset: 21n * DAY,
      slipSeconds: Number(slipDays * DAY),
      vendor: POOR_VENDOR,
    });
  }

  // E. Liquidity: shortfall after the discount only, hard shortfall, reserve-floor boundary (== floor, floor + 1).
  {
    const gross = 1_000n * USDC;
    const discounted = gross - (gross * 200n) / 10_000n;
    const floor = 100n * USDC;
    out.push({ id: "liq-ok-with-discount-only", family: "liquidity", tags: ["liquidity", "shortfall-after-full"], gross, nowOffset: DAY, terms: termsOf(SHAPE_220), stated: MATCH(SHAPE_220), liquidity: { vaultAvailable: discounted + floor, pendingReleases: 0n, reserveFloor: floor }, evidenceOffset: 0n });
    out.push({ id: "liq-one-below-discount-boundary", family: "liquidity", tags: ["liquidity", "boundary"], gross, nowOffset: DAY, terms: termsOf(SHAPE_220), stated: MATCH(SHAPE_220), liquidity: { vaultAvailable: discounted + floor - 1n, pendingReleases: 0n, reserveFloor: floor }, evidenceOffset: 0n });
    out.push({ id: "liq-exact-full-boundary", family: "liquidity", tags: ["liquidity", "boundary"], gross, nowOffset: DAY, terms: termsOf(SHAPE_220), stated: MATCH(SHAPE_220), liquidity: { vaultAvailable: gross + floor, pendingReleases: 0n, reserveFloor: floor }, evidenceOffset: 0n });
    out.push({ id: "liq-pending-eats-headroom", family: "liquidity", tags: ["liquidity", "pending"], gross, nowOffset: DAY, terms: termsOf(SHAPE_220), stated: MATCH(SHAPE_220), liquidity: { vaultAvailable: 3n * gross, pendingReleases: 2n * gross - 1n, reserveFloor: floor }, evidenceOffset: 0n });
    for (const [i, vault] of [gross / 2n, 0n, gross - 1n].entries()) {
      out.push({ id: `liq-hard-shortfall-${i}`, family: "liquidity", tags: ["liquidity", "hold"], gross, nowOffset: DAY, terms: termsOf(SHAPE_220), stated: MATCH(SHAPE_220), liquidity: { vaultAvailable: vault, pendingReleases: 0n, reserveFloor: floor }, evidenceOffset: 0n });
    }
    out.push({
      id: "liq-later-obligation-shortfall",
      family: "liquidity",
      tags: ["liquidity", "hindsight-shortfall"],
      gross,
      nowOffset: DAY,
      terms: termsOf(SHAPE_220),
      stated: MATCH(SHAPE_220),
      liquidity: { vaultAvailable: gross + 300n * USDC, pendingReleases: 0n, reserveFloor: 50n * USDC },
      evidenceOffset: 0n,
      obligation: { atOffsetSeconds: Number(6n * DAY), amount: 400n * USDC, inflow: 0n },
    });
  }

  // F. Coincident plans (two modes with the same payAt and amount) and evidence timing variants.
  for (const [i, buffer] of [48, 48, 24, 72].entries()) {
    out.push({
      id: `coincident-${i}`,
      family: "coincident",
      tags: ["coincident", "duplicate-plans"],
      nowOffset: BigInt(i) * DAY,
      terms: { netDays: 12, earlyPay: { discountBps: 200, withinDays: 10 }, payBeforeDueBufferHours: buffer, allowImmediate: true },
      stated: { netDays: 12, earlyPay: { discountBps: 200, withinDays: 10 }, ambiguous: false, label: "2/10 net 12" },
      timing: { windowSafetyMarginMinutes: 0 },
      evidenceOffset: 0n,
    });
  }
  for (const [name, evidenceOffset, nowOffset, slip] of [
    ["evidence-before-window", 1n * DAY, 2n * DAY, 0],
    ["evidence-inside-window", 5n * DAY, 2n * DAY, 0],
    ["evidence-after-window", 12n * DAY, 2n * DAY, 0],
    ["evidence-none", null, 2n * DAY, 0],
    ["evidence-slips-out-of-window", 6n * DAY, 2n * DAY, Number(6n * DAY)],
    ["evidence-dispute-window", 3n * DAY, 3n * DAY, 0],
  ] as const) {
    out.push({
      id: name,
      family: "evidence",
      tags: ["evidence", name],
      nowOffset,
      terms: termsOf(SHAPE_220),
      stated: MATCH(SHAPE_220),
      evidenceOffset,
      slipSeconds: slip,
      timing: name === "evidence-dispute-window" ? { disputeWindowHours: 72 } : {},
      vendor: slip > 0 ? POOR_VENDOR : CLEAN_VENDOR,
    });
  }
  return out.map(build);
}

// --- generated family ----------------------------------------------------------------------------------------------------

function generated(seed: number, count: number): PlannerScenario[] {
  const out: PlannerScenario[] = [];
  for (let i = 0; i < count; i++) {
    const rnd = mulberry32((seed * 1_000_003 + i * 7_919) >>> 0);
    const pick = <T>(xs: readonly T[]): T => xs[Math.floor(rnd() * xs.length)] as T;
    const chance = (p: number): boolean => rnd() < p;

    const shape = pick(SHAPES);
    const gross = pick(GROSS_CHOICES);
    const buffer = pick([0, 24, 48, 72]);
    const allowImmediate = chance(0.7);
    const dispute = pick([0, 0, 24, 48]);
    const margin = pick([0, 30, 60, 120]);
    const withinSec = BigInt(shape.early?.withinDays ?? 5) * DAY;
    const nowOffset = pick([DAY / 2n, 2n * DAY, 4n * DAY, withinSec - 2n * HOUR, withinSec + 3n * DAY, BigInt(shape.netDays - 3) * DAY, BigInt(shape.netDays + 4) * DAY]);
    const evidenceKind = pick(["already", "already", "projected-in-window", "projected-late", "none"] as const);
    const evidenceOffset: bigint | null =
      evidenceKind === "already" ? HOUR : evidenceKind === "projected-in-window" ? nowOffset + DAY : evidenceKind === "projected-late" ? withinSec + 2n * DAY : null;
    const liquidityKind = pick(["comfortable", "comfortable", "tight", "very-tight", "short"] as const);
    const vaultPct = liquidityKind === "comfortable" ? 1000 : liquidityKind === "tight" ? 160 : liquidityKind === "very-tight" ? 112 : 70;
    const poor = chance(0.3);
    const vendor = poor ? { paidCount: 3 + Math.floor(rnd() * 8), disputedCount: 1 + Math.floor(rnd() * 3), lateDeliveryCount: 2 + Math.floor(rnd() * 3) } : { paidCount: 8 + Math.floor(rnd() * 30), disputedCount: 0, lateDeliveryCount: Math.floor(rnd() * 2) };
    const slipProb = poor ? 0.6 : 0.1;
    const slipSeconds = chance(slipProb) && evidenceOffset !== null ? Number(pick([2n * DAY, 6n * DAY, 15n * DAY])) : 0;
    const obligation = chance(0.35) ? { atOffsetSeconds: Number(pick([DAY, 5n * DAY, 12n * DAY])), amount: (gross * BigInt(pick([40, 100]))) / 100n, inflow: chance(0.5) ? gross : 0n } : null;
    const ceilingKind = pick(["none", "none", "none", "90", "98"] as const);
    const ceiling = ceilingKind === "none" ? null : (gross * BigInt(ceilingKind)) / 100n;
    const statedKind = pick(["match", "match", "silent"] as const);
    out.push(
      build({
        id: `gen-${seed}-${String(i).padStart(3, "0")}`,
        family: "generated",
        tags: ["generated", `shape-${shape.label.replace(/[ /.]/g, "-")}`, `liquidity-${liquidityKind}`, `evidence-${evidenceKind}`, poor ? "vendor-poor" : "vendor-clean"],
        gross,
        nowOffset,
        terms: termsOf(shape, buffer, allowImmediate),
        stated: statedKind === "match" ? MATCH(shape) : SILENT,
        timing: { disputeWindowHours: dispute, windowSafetyMarginMinutes: margin },
        costBps: pick([0, 300, 600, 1200, 2400]),
        immediateMilestone: chance(0.15),
        evidenceOffset,
        liquidityMult: { vaultPct, pendingPct: chance(0.25) ? 20 : 0, floorPct: pick([5, 10]) },
        ceiling,
        vendor,
        slipSeconds,
        obligation,
      }),
    );
  }
  return out;
}

export const GENERATED_COUNT = 110;
export const DEFAULT_SEED = 35;

export function buildCorpus(seed: number = DEFAULT_SEED): readonly PlannerScenario[] {
  const all = [...structured(), ...generated(seed, GENERATED_COUNT)];
  const ids = new Set(all.map((s) => s.id));
  if (ids.size !== all.length) throw new Error("planner corpus has duplicate scenario ids");
  return all;
}

/** JSON-safe form (bigint as decimal strings) for hashing and reports. */
export function scenarioWire(s: PlannerScenario): Record<string, unknown> {
  return {
    ...s,
    grossBaseUnits: s.grossBaseUnits.toString(),
    liquidity: { vaultAvailable: s.liquidity.vaultAvailable.toString(), pendingReleases: s.liquidity.pendingReleases.toString(), reserveFloor: s.liquidity.reserveFloor.toString() },
    amountCeiling: s.amountCeiling === null ? null : s.amountCeiling.toString(),
    hindsight: {
      evidenceSlipSeconds: s.hindsight.evidenceSlipSeconds,
      obligation: s.hindsight.obligation === null ? null : { atOffsetSeconds: s.hindsight.obligation.atOffsetSeconds, amount: s.hindsight.obligation.amount.toString(), inflow: s.hindsight.obligation.inflow.toString() },
    },
  };
}

export function corpusHash(corpus: readonly PlannerScenario[]): Hex32 {
  return sha256Utf8(jcs(corpus.map(scenarioWire)));
}
